SELECT T.INDENTIFY_MARK as indentifyMark, T.REGIST_BANK_CODE as bankCode, T.ORG_INDENTIFY_MARK as orgIndentifyMark, T.IS_BELONG_BANK as isBelongBank, T.THE_BANK_NAME as theBankName, T.THE_BANK_CODE as theBankCode, T.HOLDER_MARK as holderMark, T.HOLDER_REGION as holderRegion, T.HOLDER_TYPE as holderType, T.PERSONAL_IDENTIFY_TYPE as personalIdentifyType, T.INSTITUTION_IDENTIFY_TYPE as institutionIdentifyType, ifnull(T.PERSONAL_IDENTIFY_TYPE,T.INSTITUTION_IDENTIFY_TYPE) as inentifyType, T.IDENTIFY_NUMBER as identifyNumber, T.OTHER_IDENTIFY_NAME as otherIdentifyName, T.SPV_CAP_ACC_BANK as spvCapAccBank, T.OTHER_CAP_ACC_BANK as otherCapAccBank, T.SPV_REGIST_CODE as spvRegistCode, T.HOLDER_NAME as holderName, T.HOLDER_SEX as holderSex, T.HOLDER_RISK_PREFER as holderRiskPrefer, T.HOLDER_CELLPHONE as holderCellphone, T.HOLDER_TELEPHONE as holderTelephone, T.HOLDER_EMAIL as holderEmail, T.REMARK as remark, T.ORG_CODE orgCode, T.STATUS as status, '' as interfCheckResult, T.HOLDER_CLASSIFY as holderClassify, T.FUND_ACC_PLACE as fundAccPlace, '' as agent, T.SUBMIT_FEEDBACK_MSG as repFailedInfo FROM CHB_EQU_SUB T
