insert into CHB_EQU_HOLD (INDENTIFY_MARK, REGIST_BANK_CODE, ORG_INDENTIFY_MARK, IS_BELONG_BANK, THE_BANK_NAME, THE_BANK_CODE, HOLDER_MARK, HOLDER_REGION, HOLDER_TYPE, PERSONAL_IDENTIFY_TYPE, INSTITUTION_IDENTIFY_TYPE, OTHER_IDENTIFY_NAME, IDENTIFY_NUMBER, SPV_CAP_ACC_BANK, OTHER_CAP_ACC_BANK, SPV_REGIST_CODE, HOLDER_DATE, HOLDER_NAME, HOLDER_SEX, HOLDER_RISK_PREFER, HOLDER_CELLPHONE, HOLDER_TELEPHONE, IS_SUBMIT, HOLDER_EMAIL, REMARK, STATUS, WORKFLOW_ID, DEPT_CODE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, DATA_SOURCE,ORG_CODE ,AGENT, CREATE_DEPT,INTERF_CHECK_RESULT,HOLDER_CLASSIFY,FUND_ACC_PLACE) select A.* from (
select #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK, #{item.bankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.orgIndentifyMark,jdbcType=VARCHAR} ORG_INDENTIFY_MARK, #{item.isBelongBank,jdbcType=CHAR} IS_BELONG_BANK, #{item.theBankName,jdbcType=VARCHAR} THE_BANK_NAME, #{item.theBankCode,jdbcType=VARCHAR} THE_BANK_CODE, #{item.holderMark,jdbcType=CHAR} HOLDER_MARK, #{item.holderRegion,jdbcType=VARCHAR} HOLDER_REGION, #{item.holderType,jdbcType=CHAR} HOLDER_TYPE, #{item.personalIdentifyType,jdbcType=CHAR} PERSONAL_IDENTIFY_TYPE, #{item.institutionIdentifyType,jdbcType=VARCHAR} INSTITUTION_IDENTIFY_TYPE, #{item.otherIdentifyName,jdbcType=VARCHAR} OTHER_IDENTIFY_NAME, #{item.identifyNumber,jdbcType=VARCHAR} IDENTIFY_NUMBER, #{item.spvCapAccBank,jdbcType=VARCHAR} SPV_CAP_ACC_BANK, #{item.otherCapAccBank,jdbcType=VARCHAR} OTHER_CAP_ACC_BANK, #{item.spvRegistCode,jdbcType=VARCHAR} SPV_REGIST_CODE, null HOLDER_DATE, #{item.holderName,jdbcType=VARCHAR} HOLDER_NAME, #{item.holderSex,jdbcType=CHAR} HOLDER_SEX, #{item.holderRiskPrefer,jdbcType=VARCHAR} HOLDER_RISK_PREFER, #{item.holderCellphone,jdbcType=VARCHAR} HOLDER_CELLPHONE, #{item.holderTelephone,jdbcType=VARCHAR} HOLDER_TELEPHONE, #{item.isSubmit,jdbcType=CHAR} IS_SUBMIT, #{item.holderEmail,jdbcType=VARCHAR} HOLDER_EMAIL, #{item.remark,jdbcType=VARCHAR} REMARK, 'E' STATUS, '' WORKFLOW_ID, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, now() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, now() CREATE_TIME, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.agent,jdbcType=VARCHAR} AGENT, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.interfCheckResult,jdbcType=VARCHAR} INTERF_CHECK_RESULT, #{item.holderClassify,jdbcType=CHAR} HOLDER_CLASSIFY, #{item.fundAccPlace,jdbcType=CHAR} FUND_ACC_PLACE from dual
) A

