select INDENTIFY_MARK from ( SELECT ciis.INDENTIFY_MARK,SUM(ciis.QTY) qty FROM CHB_INVESTHOLD_INFO_SUB ciis inner join (SELECT REGIST_BANK_CODE,INDENTIFY_MARK,MAX(HOLD_DATE) maxDate FROM CHB_INVESTHOLD_INFO_SUB where SEND_STATUS != #{unSubmit} and STATUS != #{statusD}
(#{item.indentifyMark,jdbcType=VARCHAR},#{item.bankCode,jdbcType=VARCHAR})
GROUP BY INDENTIFY_MARK, REGIST_BANK_CODE) ciis2 on ciis.REGIST_BANK_CODE = ciis2.REGIST_BANK_CODE and ciis.INDENTIFY_MARK = ciis2.INDENTIFY_MARK and ciis.HOLD_DATE = ciis2.maxDate where ciis.SEND_STATUS != #{unSubmit} and ciis.STATUS != #{statusD} GROUP BY ciis.INDENTIFY_MARK ) tmp where qty>0

